package robofight.fireline

import kotlin.test.assertNotNull

/**
 * Hand-written helper (not generated by `parity_fixture_gen.py`): rebuild the
 * mission that each row of `docs/web/fixtures/parity_matrix.tsv` describes.
 *
 * The ten authored rows resolve through [Missions.byId], whose layout and
 * firmware are committed in `Missions.kt`. The four E2 wall rows of
 * `PLAN-EDGE-WALLS.md` §7 step E2 ship no authored mission (step E5 owns
 * content), so they are rebuilt from the pinned canonical mission text and the
 * pinned firmware text in [PARITY_WALL_LAYOUT_TEXTS] and
 * [PARITY_WALL_FIRMWARE_TEXTS], plus the rule columns the row records. That is
 * what makes the wall rows assertable on both `jvm` and `wasmJs`: the same
 * generated fixture data drives the same recomputation on every target.
 */

/** `kind` values of the E2 wall fixture rows in `parity_matrix.tsv`. */
internal val PARITY_WALL_KINDS: Set<String> = setOf("wall", "wall-open")

internal fun ParityFixtureRow.isWallFixture(): Boolean = kind in PARITY_WALL_KINDS

internal fun parityWallRows(): List<ParityFixtureRow> = PARITY_FIXTURE_ROWS.filter { it.isWallFixture() }

internal fun parityMissionRows(): List<ParityFixtureRow> = PARITY_FIXTURE_ROWS.filter { !it.isWallFixture() }

/** Pinned canonical layout text of a wall row, or a loud failure. */
internal fun parityWallLayoutText(row: ParityFixtureRow): String =
    assertNotNull(
        PARITY_WALL_LAYOUT_TEXTS[row.scenario],
        "docs/web/fixtures/parity_fixture_gen.py pinned no layout text for row ${row.scenario}",
    )

/** Pinned firmware source of a wall row, or a loud failure. */
internal fun parityWallFirmwareText(row: ParityFixtureRow): String =
    assertNotNull(
        PARITY_WALL_FIRMWARE_TEXTS[row.scenario],
        "docs/web/fixtures/parity_fixture_gen.py pinned no firmware text for row ${row.scenario}",
    )

private object W2FixtureMissions {
    private val cache = HashMap<String, Mission>()

    fun missionOf(row: ParityFixtureRow): Mission = cache.getOrPut(row.scenario) { build(row) }

    private fun build(row: ParityFixtureRow): Mission {
        if (!row.isWallFixture()) {
            return assertNotNull(
                Missions.byId(row.missionId),
                "docs/web/fixtures/parity_matrix.tsv row ${row.scenario} names mission ${row.missionId} which does not exist",
            )
        }
        return Mission(
            id = row.missionId,
            name = row.missionName,
            briefing = "E2 wall fixture layout (PLAN-EDGE-WALLS.md §7 step E2, fixture content only)",
            layout = Layout.fromCanonicalText(parityWallLayoutText(row)),
            seed = row.seed,
            objectives = row.objectives,
            timeLimit = row.timeLimit,
            surviveUntil = row.surviveUntil,
            startingWater = row.startingWater,
            windDir = row.windDir,
            windForce = row.windForce,
            referenceSource = parityWallFirmwareText(row),
            failingSources = emptyList(),
            maxTicks = row.maxTicks,
        ).requireValid()
    }

    fun sourceOf(row: ParityFixtureRow): String {
        if (row.isWallFixture()) return parityWallFirmwareText(row)
        val m = assertNotNull(
            Missions.byId(row.missionId),
            "docs/web/fixtures/parity_matrix.tsv row ${row.scenario} names mission ${row.missionId} which does not exist",
        )
        if (row.kind == "reference") return m.referenceSource
        val found = m.failingSources.firstOrNull { it.first == row.firmwareLabel }
        return assertNotNull(
            found,
            "mission ${m.id} does not carry a failing firmware labelled ${row.firmwareLabel}",
        ).second
    }
}

/** The mission a fixture row describes (authored mission, or rebuilt wall layout). */
internal fun parityMissionOf(row: ParityFixtureRow): Mission = W2FixtureMissions.missionOf(row)

/** The firmware source a fixture row ran. */
internal fun paritySourceOf(row: ParityFixtureRow): String = W2FixtureMissions.sourceOf(row)

/** Count the wall glyphs in a pinned wall layout text without asking the engine. */
internal fun parityWallGlyphCount(text: String): Int {
    val lines = text.split('\n')
    var walls = 0
    var i = 0
    while (i < lines.size) {
        val (rows, cols) = when (lines[i]) {
            SECTION_WALL_VERT -> WALL_VERT_ROWS to VERT_EDGE_COLUMNS
            SECTION_WALL_HORIZ -> WALL_HORIZ_ROWS to GRID
            else -> { i++; continue }
        }
        for (r in 0 until rows) {
            val line = lines[i + 1 + r]
            check(line.length == cols) { "wall section ${lines[i]} row $r is ${line.length} chars, expected $cols" }
            walls += line.count { it == EDGE_GLYPH_WALL }
        }
        i += rows + 1
    }
    return walls
}
